package com.fuelflex.platform.operations.entity;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;import com.fuelflex.platform.product.entity.Product;import com.fuelflex.platform.tank.entity.Tank;import jakarta.persistence.*;import lombok.*;
@Entity @Table(name="internal_consumption_stock_movements")@Getter @Setter @NoArgsConstructor public class InternalConsumptionStockMovement{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="internal_consumption_id")private InternalConsumption internalConsumption;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="tank_id")private Tank tank;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id")private Product product;@Column(nullable=false,precision=19,scale=3)private BigDecimal quantity;@Column(name="movement_type",nullable=false)private String movementType="INTERNAL_CONSUMPTION";@Column(name="created_at",nullable=false)private OffsetDateTime createdAt;@PrePersist void create(){if(createdAt==null)createdAt=OffsetDateTime.now();}}
